import xarray as xr
import numpy as np

def test_keep_attrs_false_drops_coords_attrs():
    # Create a DataArray with attributes on its coordinate
    da = xr.DataArray(
        np.arange(3),
        dims="x",
        coords={"x": [0, 1, 2]},
        attrs={"da_attr": "da_val"}
    )
    da.x.attrs = {"x_attr": "x_val"}

    # Use apply_ufunc with keep_attrs=False
    # We need a function that returns something to trigger the merge
    def func(x):
        return x * 2

    result = xr.apply_ufunc(
        func,
        da,
        keep_attrs=False
    )

    # The result should have no attributes
    assert result.attrs == {}
    # The original DataArray's coordinate should STILL have its attributes
    assert da.x.attrs == {"x_attr": "x_val"}, f"Coordinate attributes were dropped! Got {da.x.attrs}"

if __name__ == "__main__":
    try:
        test_keep_attrs_false_drops_coords_attrs()
        print("Test passed!")
    except AssertionError as e:
        print(f"Test failed: {e}")
        exit(1)

